-- W3BS DE defaults (built on Hyprland). https://w3bs.org/de
--
-- Do not edit this file: `w3bs-de update` replaces it. Put your own settings in
-- ~/.config/w3bs-de/hypr/user.lua, which loads after this one and wins.
--
-- Minimal and agent-friendly:
--   * one bar, one launcher, one notification center, no animations that move targets late;
--   * the Agentic Desktop Layer starts with the session (Disabled until you enable it), its tray
--     sits in the bar, and SUPER + ALT + Escape always turns agent access off;
--   * an "agent" scratch workspace (SUPER + SHIFT + A) where agents can work out of your way.

local share = os.getenv("W3BS_DE_SHARE") or ((os.getenv("HOME") or "") .. "/.local/share/w3bs-de")
local d = share .. "/default"

w3bs = w3bs or {}
w3bs.share = share
w3bs.terminal = os.getenv("W3BS_DE_TERMINAL") or ("foot --config=" .. d .. "/foot/foot.ini")
w3bs.launcher = "fuzzel --config=" .. d .. "/fuzzel/fuzzel.ini"
w3bs.browser = os.getenv("W3BS_DE_BROWSER") or "xdg-open https://w3bs.org"

-- Palette (w3bs.org tokens): ink, paper, orange, sage, muted.
w3bs.colors = {
  ink = "rgb(1c2b26)",
  paper = "rgb(f6f4ed)",
  orange = "rgb(d95231)",
  sage = "rgb(e6ebdc)",
  muted = "rgba(6b726899)",
}

-- ---------------------------------------------------------------- environment

hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "w3bs-de")
hl.env("W3BS_DE", "1")
hl.env("W3BS_DE_SHARE", share)
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("MOZ_ENABLE_WAYLAND", "1")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "wayland")
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })

-- ---------------------------------------------------------------- look and feel

hl.config({
  general = {
    gaps_in = 4,
    gaps_out = 8,
    border_size = 2,
    col = {
      active_border = w3bs.colors.orange,
      inactive_border = w3bs.colors.muted,
    },
    resize_on_border = true,
    layout = "dwindle",
    allow_tearing = false,
  },
  decoration = {
    rounding = 6,
    shadow = { enabled = false },
    blur = { enabled = false },
  },
  -- Short and few: a window an agent just opened is where it says it is.
  animations = { enabled = true },
  dwindle = {
    preserve_split = true,
    force_split = 2,
  },
  input = {
    kb_layout = "us",
    follow_mouse = 1,
    sensitivity = 0,
    touchpad = { natural_scroll = true },
  },
  misc = {
    disable_hyprland_logo = true,
    disable_splash_rendering = true,
    background_color = w3bs.colors.ink,
    focus_on_activate = true,
    allow_session_lock_restore = true,
  },
  ecosystem = {
    no_update_news = true,
    no_donation_nag = true,
  },
  xwayland = { force_zero_scaling = true },
})

hl.curve("w3bs", { type = "bezier", points = { { 0.2, 1 }, { 0.3, 1 } } })
hl.animation({ leaf = "global", enabled = true, speed = 4, bezier = "w3bs" })
hl.animation({ leaf = "windows", enabled = true, speed = 2.5, bezier = "w3bs", style = "popin 92%" })
hl.animation({ leaf = "fade", enabled = true, speed = 2.5, bezier = "w3bs" })
hl.animation({ leaf = "workspaces", enabled = false })

-- ---------------------------------------------------------------- windows

hl.window_rule({ match = { class = "^(pavucontrol|nm-connection-editor|blueman-manager|org.pulseaudio.pavucontrol)$" }, float = true })
hl.window_rule({ match = { class = "^(hyprpolkitagent|polkit.*|gcr-prompter|pinentry.*)$" }, float = true, center = true, pin = true })
-- The control app and the agent's own windows stay where you can see them.
hl.window_rule({ match = { title = "^(Agentic Desktop Layer.*)$" }, float = true, center = true })

-- ---------------------------------------------------------------- bindings

local function bind(keys, description, action, opts)
  opts = opts or {}
  opts.description = description
  if type(action) == "string" then
    action = hl.dsp.exec_cmd(action)
  end
  hl.bind(keys, action, opts)
end
w3bs.bind = bind

bind("SUPER + RETURN", "Terminal", w3bs.terminal)
bind("SUPER + SPACE", "Launcher", w3bs.launcher)
bind("SUPER + B", "Browser", w3bs.browser)
bind("SUPER + N", "Notifications", "swaync-client -t -sw")
bind("SUPER + W", "Close window", hl.dsp.window.close())
bind("SUPER + Q", "Close window", hl.dsp.window.close())
bind("SUPER + T", "Float / tile", hl.dsp.window.float({ action = "toggle" }))
bind("SUPER + F", "Full screen", hl.dsp.window.fullscreen({ mode = "fullscreen" }))
bind("SUPER + J", "Toggle split", hl.dsp.layout("togglesplit"))
bind("SUPER + ESCAPE", "Lock", "hyprlock --config " .. d .. "/hypr/hyprlock.conf")
bind("SUPER + SHIFT + ESCAPE", "Log out", "w3bs-de logout")
bind("PRINT", "Screenshot of a region to the clipboard", "w3bs-de screenshot region")
bind("SHIFT + PRINT", "Screenshot of the screen to ~/Pictures", "w3bs-de screenshot screen")

for _, dir in ipairs({ { "LEFT", "l" }, { "RIGHT", "r" }, { "UP", "u" }, { "DOWN", "d" } }) do
  bind("SUPER + " .. dir[1], "Focus " .. dir[2], hl.dsp.focus({ direction = dir[2] }))
  bind("SUPER + SHIFT + " .. dir[1], "Swap " .. dir[2], hl.dsp.window.swap({ direction = dir[2] }))
end
for ws = 1, 9 do
  local key = "code:" .. tostring(ws + 9)
  bind("SUPER + " .. key, "Workspace " .. ws, hl.dsp.focus({ workspace = ws }))
  bind("SUPER + SHIFT + " .. key, "Move window to workspace " .. ws, hl.dsp.window.move({ workspace = ws }))
end
bind("SUPER + TAB", "Next workspace", hl.dsp.focus({ workspace = "m+1" }))
bind("SUPER + SHIFT + TAB", "Previous workspace", hl.dsp.focus({ workspace = "m-1" }))
bind("SUPER + mouse:272", "Move window", hl.dsp.window.drag(), { mouse = true })
bind("SUPER + mouse:273", "Resize window", hl.dsp.window.resize(), { mouse = true })

-- Agents.
bind("SUPER + A", "Agent control panel", "w3bs-desktop control --open")
bind("SUPER + SHIFT + A", "Agent workspace", hl.dsp.workspace.toggle_special("agent"))
bind("SUPER + ALT + A", "Move window to the agent workspace", hl.dsp.window.move({ workspace = "special:agent", follow = false }))
bind("SUPER + ALT + ESCAPE", "Turn agent access off", "w3bs-desktop disable")

-- Media keys.
bind("XF86AudioRaiseVolume", "Volume up", "wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+", { repeating = true, locked = true })
bind("XF86AudioLowerVolume", "Volume down", "wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-", { repeating = true, locked = true })
bind("XF86AudioMute", "Mute", "wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle", { locked = true })
bind("XF86MonBrightnessUp", "Brightness up", "brightnessctl -e4 -n2 set 5%+", { repeating = true, locked = true })
bind("XF86MonBrightnessDown", "Brightness down", "brightnessctl -e4 -n2 set 5%-", { repeating = true, locked = true })

-- ---------------------------------------------------------------- session

hl.on("hyprland.start", function()
  -- Services started outside the session (the agent broker) need its environment.
  hl.exec_cmd("dbus-update-activation-environment --systemd --all")
  hl.exec_cmd("w3bs-de autostart")
end)
